import type { ComponentProps, CSSProperties } from "react";
import type { ChatMessageKnobStyle } from "@/components/control-ui/knob-contracts/chat-message-knobs";

export type ChatRole = "user" | "assistant" | "system" | "tool";

export type ChatDensity = "compact" | "comfortable";

export type ChatState = "idle" | "streaming" | "pending" | "error";

export type ChatMessageProps = ComponentProps<"article"> & {
  from: ChatRole;
  state?: ChatState;
  density?: ChatDensity;
} & { style?: CSSProperties & ChatMessageKnobStyle };

export type ChatMessageContext = {
  from: ChatRole;
  state: ChatState;
  density: ChatDensity;
  isUser: boolean;
  isAssistant: boolean;
  isSystem: boolean;
  isTool: boolean;
  isCompact: boolean;
  isStreaming: boolean;
  isError: boolean;
};

function getChatMessageContext({
  from,
  state,
  density,
}: Required<Pick<ChatMessageProps, "from" | "state" | "density">>): ChatMessageContext {
  return {
    from,
    state,
    density,
    isUser: from === "user",
    isAssistant: from === "assistant",
    isSystem: from === "system",
    isTool: from === "tool",
    isCompact: density === "compact",
    isStreaming: state === "streaming",
    isError: state === "error",
  };
}

export function useChatMessage({ from, state = "idle", density = "comfortable" }: Pick<ChatMessageProps, "from" | "state" | "density">) {
  return getChatMessageContext({ from, state, density });
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { createContext, useContext } from "react";

import type { ChatMessageProps } from "@/components/control-ui/hooks/use-chat-message";
import { useChatMessage } from "@/components/control-ui/hooks/use-chat-message";
import type { ChatMessageKnobStyle } from "@/components/control-ui/knob-contracts/chat-message-knobs";
import { cn } from "@/components/control-ui/lib/cn";

type ChatMessageContextValue = ReturnType<typeof useChatMessage>;

const ChatMessageContext = createContext<ChatMessageContextValue | null>(null);

function useChatMessageContext() {
  const context = useContext(ChatMessageContext);
  if (!context) throw new Error("ChatMessage compound components must be rendered inside <ChatMessage>.");
  return context;
}

export function ChatMessage({ from, state = "idle", density = "comfortable", className, children, ...props }: ChatMessageProps) {
  const message = useChatMessage({ from, state, density });

  return (
    <ChatMessageContext.Provider value={message}>
      <article
        data-control-ui="chat-message"
        data-control-family="chat-message"
        data-slot="root"
        data-role={from}
        data-state={state}
        data-density={density}
        className={cn("w-full", className)}
        {...props}
      >
        {children}
      </article>
    </ChatMessageContext.Provider>
  );
}

export type ChatMessageRowProps = ComponentProps<"div"> & { style?: CSSProperties & ChatMessageKnobStyle };

export function ChatMessageRow({ className, children, ...props }: ChatMessageRowProps) {
  const message = useChatMessageContext();

  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="row"
      className={cn("flex w-full", message.isUser ? "justify-end" : "justify-start", className)}
      {...props}
    >
      {children}
    </div>
  );
}

export type ChatMessageAvatarProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageAvatar({ className, ...props }: ChatMessageAvatarProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="avatar"
      className={cn("flex shrink-0 items-center justify-center", className)}
      {...props}
    />
  );
}

export type ChatMessageBodyProps = ComponentProps<"div"> & { style?: CSSProperties & ChatMessageKnobStyle };

export function ChatMessageBody({ className, ...props }: ChatMessageBodyProps) {
  useChatMessageContext();

  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="body"
      className={cn("min-w-0", className)}
      {...props}
    />
  );
}

export type ChatMessageHeaderProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageHeader({ className, ...props }: ChatMessageHeaderProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="header"
      className={cn("flex items-center", className)}
      {...props}
    />
  );
}

export type ChatMessageContentProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageContent({ className, ...props }: ChatMessageContentProps) {
  const message = useChatMessageContext();

  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="content"
      data-role={message.from}
      data-streaming={message.isStreaming ? "" : undefined}
      className={cn(message.isUser && "px-[var(--padding-x)] py-[var(--padding-y)]", className)}
      {...props}
    />
  );
}

export type ChatMessageActionsProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageActions({ className, ...props }: ChatMessageActionsProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="actions"
      className={cn("flex items-center", className)}
      {...props}
    />
  );
}

@layer components {
  :where([data-control-family="chat-message"][data-slot="root"]) {
    --cui-chat-message-avatar-radius: 9999px;
    --cui-chat-message-avatar-background: var(--card);
    --cui-chat-message-avatar-border-color: var(--border);
    --cui-chat-message-avatar-border-width: 1px;
    --cui-chat-message-radius: 0px;
    --cui-chat-message-corner-radius: 0px;
    --cui-chat-message-background: transparent;
    --cui-chat-message-background-image: none;
    --cui-chat-message-foreground: var(--foreground);
    --cui-chat-message-border-color: transparent;
    --cui-chat-message-border-width: 0px;
    --cui-chat-message-shadow: none;
  }
  :where([data-control-family="chat-message"][data-slot="row"]) {
    gap: calc(var(--spacing) * 2);
    padding-block: calc(var(--spacing) * 2);
  }

  :where([data-control-family="chat-message"][data-slot="root"][data-density="compact"] [data-slot="row"]) {
    padding-block: calc(var(--spacing) * 1);
  }

  :where([data-control-family="chat-message"][data-slot="root"][data-role="user"] [data-slot="body"]) {
    max-inline-size: 76%;
  }

  :where([data-control-family="chat-message"][data-slot="root"]:not([data-role="user"]) [data-slot="body"]) {
    max-inline-size: 80%;
    flex: 1;
  }

  :where([data-control-family="chat-message"][data-slot="avatar"]) {
    margin-block-start: calc(var(--spacing) * 0.5);
    inline-size: calc(var(--spacing) * 6);
    block-size: calc(var(--spacing) * 6);
    border: var(--cui-chat-message-avatar-border-width) solid var(--cui-chat-message-avatar-border-color);
    border-radius: var(--cui-chat-message-avatar-radius);
    background: var(--cui-chat-message-avatar-background);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="content"]) {
    border: var(--cui-chat-message-border-width) solid var(--cui-chat-message-border-color);
    border-radius: var(--cui-chat-message-radius);
    border-start-end-radius: var(--cui-chat-message-corner-radius);
    background-color: var(--cui-chat-message-background);
    background-image: var(--cui-chat-message-background-image);
    box-shadow: var(--cui-chat-message-shadow);
    color: var(--cui-chat-message-foreground);
    font-size: var(--text-body);
    line-height: calc(var(--spacing) * 5);
  }

  :where([data-control-family="chat-message"][data-slot="root"][data-role="user"]) {
    --cui-chat-message-radius: var(--radius-field);
    --cui-chat-message-corner-radius: var(--radius-lg);
    --cui-chat-message-background: var(--primary);
    --cui-chat-message-foreground: var(--primary-foreground);
    --cui-chat-message-shadow: var(--shadow-sm);
  }

  :where([data-control-family="chat-message"][data-slot="content"][data-role="assistant"][data-streaming]) {
    @apply shimmer-text;
  }
  :where([data-control-family="chat-message"][data-slot="actions"]) {
    margin-block-start: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 1);
    opacity: 0;
    transition-property: opacity;
    transition-timing-function: var(--ease-standard);
    transition-duration: var(--duration-fast);
  }

  @media (hover: hover) {
    :where([data-control-family="chat-message"][data-slot="row"]:hover [data-control-family="chat-message"][data-slot="actions"]) {
      opacity: 1;
    }
  }

  :where([data-control-family="chat-message"][data-slot="header"]) {
    margin-block-end: calc(var(--spacing) * 1);
    gap: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 1);
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }
}

